e\";s:10:\"image/jpeg\";s:8:\"filesize\";i:18099;}s:5:\"large\";a:5:{s:4:\"file\";s:21:\"IMG_5903-814x1024.jpg\";s:5:\"width\";i:814;s:6:\"height\";i:1024;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:123069;}s:9:\"thumbnail\";a:5:{s:4:\"file\";s:20:\"IMG_5903-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:7671;}s:12:\"medium_large\";a:5:{s:4:\"file\";s:20:\"IMG_5903-768x967.jpg\";s:5:\"width\";i:768;s:6:\"height\";i:967;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:112489;}}s:10:\"image_meta\";a:13:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:10:\"Screenshot\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:10:\"Screenshot\";s:11:\"orientation\";s:1:\"1\";s:8:\"keywords\";a:0:{}s:3:\"alt\";s:0:\"\";}}'),(32,17,'_wp_attachment_image_alt','Construction workers attending a safety training classroom'),(33,7,'_wp_page_template','page-no-title'),(34,8,'_wp_page_template','page-no-title'),(35,26,'_wp_page_template','page-no-title'),(36,27,'_wp_page_template','page-no-title'),(37,28,'_wp_page_template','page-no-title'),(38,29,'_wp_page_template','page-no-title');
