- /wp:heading -->\n\n  <!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"32px\",\"left\":\"32px\"}}}} -->\n  <div class=\"wp-block-columns alignwide\">\n    <!-- wp:column {\"width\":\"33.33%\"} -->\n    <div class=\"wp-block-column\" style=\"flex-basis:33.33%\">\n      <!-- wp:image {\"id\":13,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"12px\"}}} -->\n      <figure class=\"wp-block-image size-large has-custom-border\"><img src=\"http://localhost:8080/wp-content/uploads/2026/06/IMG_7220.jpg\" alt=\"School campus exterior\" class=\"wp-image-13\" style=\"border-radius:12px;width:100%;height:240px;object-fit:cover\" /></figure>\n      <!-- /wp:image -->\n      <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\",\"fontWeight\":\"600\"}},\"textColor\":\"slate-900\"} -->\n      <h3 class=\"wp-block-heading\" style=\"font-size:1.5rem;font-weight:600;color:#0f172a;margin-top:20px;margin-bottom:8px\">Our Campus</h3>\n      <!-- /wp:heading -->\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1rem\",\"lineHeight\":\"1.5\"}},\"textColor\":\"slate-600\"} -->\n      <p style=\"font-size:1rem;line-height:1.5;color:#475569\">A welcoming and modern campus designed to foster collaboration and interactive learning.</p>\n      <!-- /wp:paragraph -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"width\":\"33.33%\"} -->\n    <div class=\"wp-block-column\" style=\"flex-basis:33.33%\">\n      <!-- wp:image {\"id\":14,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"12px\"}}} -->\n      <figure class=\"wp-block-image size-large has-custom-border\"><img src=\"http://localhost:8080/wp-content/uploads/2026/06/IMG_3486.jpg\" alt=\"Interactive classroom\" class=\"wp-image-14\" style=\"border-radius:12px;width:100%;height:240px;object-fit:cover\" /></figure>\n      <!-- /wp:image -->\n      <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\",\"fontWeight\":\"600\"}},\"textColor\":\"slate-900\"} -->\n      <h3 class=\"wp-block-heading\" style=\"font-size:1.5rem;font-weight:600;color:#0f172a;margin-top:20px;margin-bottom:8px\">Interactive Classrooms</h3>\n      <!-- /wp:heading -->\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1rem\",\"lineHeight\":\"1.5\"}},\"textColor\":\"slate-600\"} -->\n      <p style=\"font-size:1rem;line-height:1.5;color:#475569\">Equipped with comfortable spaces that encourage confidence and active speaking from day one.</p>\n      <!-- /wp:paragraph -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"width\":\"33.33%\"} -->\n    <div class=\"wp-block-column\" style=\"flex-basis:33.33%\">\n      <!-- wp:image {\"id\":15,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"12px\"}}} -->\n      <figure class=\"wp-block-image size-large has-custom-border\"><img src=\"http://localhost:8080/wp-content/uploads/2026/06/IMG_8810.jpg\" alt=\"Wide classroom view\" class=\"wp-image-15\" style=\"border-radius:12px;width:100%;height:240px;object-fit:cover\" /></figure>\n      <!-- /wp:image -->\n      <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\",\"fontWeight\":\"600\"}},\"textColor\":\"slate-900\"} -->\n      <h3 class=\"wp-block-heading\" style=\"font-size:1.5rem;font-weight:600;color:#0f172a;margin-top:20px;margin-bottom:8px\">Dynamic Learning</h3>\n      <!-- /wp:heading -->\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1rem\",\"lineHeight\":\"1.5\"}},\"textColor\":\"slate-600\"} -->\n      <p style=\"font-size:1rem;line-height:1.5;color:#475569\">Experience practical language training that translates directly into your daily life and career.</p>\n      <!-- /wp:paragraph -->\n    </div>\n    <!-- /wp:column -->\n  </div>\n  <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->','Home','','inherit','closed','closed','','7-revision-v1','','','2026-06-11 19:45:06','2026-06-11 19:45:06','',7,'http://localhost:8080/?p=18',0,'revision','',0),(19,0,'2026-06-11 19:45:06','2026-06-11 19:45:06','<!-- wp:group {\"metadata\":{\"name\":\"Hero Section ES\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"24px\",\"right\":\"24px\"},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"}},\"color\":{\"background\":\"#0f172a\"}},\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-white-color has-background-color has-text-color\" style=\"margin-top:0px;margin-bottom:0px;padding-top:80px;padding-bottom:80px;padding-left:24px;padding-right:24px;background-color:#0f172a\">\n  <!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"48px\",\"left\":\"48px\"}}}} -->\n  <div class=\"wp-block-columns alignwide\">\n    <!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\"} -->\n    <div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\">\n      <!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"3.5rem\",\"fontWeight\":\"800\",\"lineHeight\":\"1.2\"}},\"textColor\":\"white\"} -->\n      <h1 class=\"wp-block-heading has-white-color has-text-color\" style=\"font-size:3.5rem;font-weight:800;line-height:1.2\">Bienvenidos a Fluent Futures</h1>\n      <!-- /wp:heading -->\n\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"lineHeight\":\"1.6\"}},\"textColor\":\"gray-300\"} -->\n      <p style=\"font-size:1.25rem;line-height:1.6;color:#d1d5db;margin:24px 0 32px 0\">En Fluent Futures ayudamos a nuestros estudiantes a comunicarse con confianza en inglés todos los días. Nuestro objetivo es hacer que el inglés sea práctico, útil y fácil de usar en la vida real, el trabajo y conversaciones diarias.</p>\n      <!-- /wp:paragraph -->\n\n      <!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\",\"orientation\":\"horizontal\"}} -->\n      <div class=\"wp-block-buttons\">\n        <!-- wp:button {\"className\":\"is-style-fill\",\"style\":{\"color\":{\"background\":\"#25d366\"}},\"textColor\":\"white\"} -->\n        <div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link has-white-color has-background-color has-text-color wp-element-button\" href=\"https://wa.me/14077605707\" style=\"background-color:#25d366;font-weight:700\" target=\"_blank\" rel=\"noreferrer noopener\">Contactar por WhatsApp</a></div>\n        <!-- /wp:button -->\n\n        <!-- wp:button {\"className\":\"is-style-outline\",\"style\":{\"border\":{\"color\":\"#ffffff\",\"width\":\"2px\"}},\"textColor\":\"white\"} -->\n        <div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link has-white-color has-text-color wp-element-button\" href=\"https://www.tiktok.com/@fluentfutures.8\" style=\"font-weight:700\" target=\"_blank\" rel=\"noreferrer noopener\">Seguir en TikTok</a></div>\n        <!-- /wp:button -->\n      </div>\n      <!-- /wp:buttons -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\"} -->\n    <div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\">\n      <!-- wp:image {\"id\":12,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"16px\"}}} -->\n      <figure class=\"wp-block-image size-large has-custom-border\"><img src=\"http://localhost:8080/wp-content/uploads/2026/06/IMG_8347.jpeg\" alt=\"Estudiantes estudiando juntos\" class=\"wp-image-12\" style=\"border-radius:16px;width:100%;height:auto\" /></figure>\n      <!-- /wp:image -->\n    </div>\n    <!-- /wp:column -->\n  </div>\n  <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Meet the Founder Section ES\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"24px\",\"right\":\"24px\"}},\"color\":{\"background\":\"#f8fafc\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background-color\" style=\"padding-top:80px;padding-bottom:80px;padding-left:24px;padding-right:24px;background-color:#f8fafc\">\n  <!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"48px\",\"left\":\"48px\"}}}} -->\n  <div class=\"wp-block-columns alignwide\">\n    <!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"45%\"} -->\n    <div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:45%\">\n      <!-- wp:image {\"id\":11,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"16px\"}}} -->\n      <figure class=\"wp-block-image size-large has-custom-border\"><img src=\"http://localhost:8080/wp-content/uploads/2026/06/168f3f2f-11c2-415d-b51c-d713d1626e79.jpg\" alt=\"Teacher Angie enseñando en el aula\" class=\"wp-image-11\" style=\"border-radius:16px;width:100%;height:auto\" /></figure>\n      <!-- /wp:image -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"55%\"} -->\n    <div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:55%\">\n      <!-- wp:heading {\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"2.25rem\",\"fontWeight\":\"700\"}},\"textColor\":\"slate-900\"} -->\n      <h2 class=\"wp-block-heading\" style=\"font-size:2.25rem;font-weight:700;color:#0f172a\">Teacher Angie — Fundadora de Fluent Futures</h2>\n      <!-- /wp:heading -->\n\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.125rem\",\"lineHeight\":\"1.7\"}},\"textColor\":\"slate-600\"} -->\n      <p style=\"font-size:1.125rem;line-height:1.7;color:#475569;margin-top:20px\">Me apasiona enseñar inglés y ayudar a mis estudiantes a crecer. Fluent Futures es más que una escuela; es una comunidad donde los estudiantes se sienten apoyados, motivados y con la confianza necesaria para mejorar cada día. También nos divertimos en el proceso.</p>\n      <!-- /wp:paragraph -->\n\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.125rem\",\"lineHeight\":\"1.7\"}},\"textColor\":\"slate-600\"} -->\n      <p style=\"font-size:1.125rem;line-height:1.7;color:#475569;margin-top:16px\">Le damos una voz a la comunidad latina y ayudamos a cerrar la brecha entre culturas en Austin.</p>\n      <!-- /wp:paragraph -->\n    </div>\n    <!-- /wp:column -->\n  </div>\n  <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"School Gallery Section ES\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"24px\",\"right\":\"24px\"}},\"color\":{\"background\":\"#ffffff\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background-color\" style=\"padding-top:80px;padding-bottom:80px;padding-left:24px;padding-right:24px;background-color:#ffffff\">\n  <!-- wp:heading {\"textAlign\":\"center\",\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"2.25rem\",\"fontWeight\":\"700\"}},\"textColor\":\"slate-900\"} -->\n  <h2 class=\"wp-block-heading has-text-align-center\" style=\"font-size:2.25rem;font-weight:700;color:#0f172a;margin-bottom:48px\">Nuestra Comunidad y Espacios de Aprendizaje</h2>\n  <!-- /wp:heading -->\n\n  <!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"32px\",\"left\":\"32px\"}}}} -->\n  <div class=\"wp-block-columns alignwide\">\n    <!-- wp:column {\"width\":\"33.33%\"} -->\n    <div class=\"wp-block-column\" style=\"flex-basis:33.33%\">\n      <!-- wp:image {\"id\":13,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"12px\"}}} -->\n      <figure class=\"wp-block-image size-large has-custom-border\"><img src=\"http://localhost:8080/wp-content/uploads/2026/06/IMG_7220.jpg\" alt=\"Fachada de la escuela\" class=\"wp-image-13\" style=\"border-radius:12px;width:100%;height:240px;object-fit:cover\" /></figure>\n      <!-- /wp:image -->\n      <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\",\"fontWeight\":\"600\"}},\"textColor\":\"slate-900\"} -->\n      <h3 class=\"wp-block-heading\" style=\"font-size:1.5rem;font-weight:600;color:#0f172a;margin-top:20px;margin-bottom:8px\">Nuestra Sede</h3>\n      <!-- /wp:heading -->\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1rem\",\"lineHeight\":\"1.5\"}},\"textColor\":\"slate-600\"} -->\n      <p style=\"font-size:1rem;line-height:1.5;color:#475569\">Un campus acogedor y moderno diseñado para fomentar la colaboración y el aprendizaje interactivo.</p>\n      <!-- /wp:paragraph -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"width\":\"33.33%\"} -->\n    <div class=\"wp-block-column\" style=\"flex-basis:33.33%\">\n      <!-- wp:image {\"id\":14,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"12px\"}}} -->\n      <figure class=\"wp-block-image size-large has-custom-border\"><img src=\"http://localhost:8080/wp-content/uploads/2026/06/IMG_3486.jpg\" alt=\"Aula de clase interactiva\" class=\"wp-image-14\" style=\"border-radius:12px;width:100%;height:240px;object-fit:cover\" /></figure>\n      <!-- /wp:image -->\n      <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\",\"fontWeight\":\"600\"}},\"textColor\":\"slate-900\"} -->\n      <h3 class=\"wp-block-heading\" style=\"font-size:1.5rem;font-weight:600;color:#0f172a;margin-top:20px;margin-bottom:8px\">Aulas Interactivas</h3>\n      <!-- /wp:heading -->\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1rem\",\"lineHeight\":\"1.5\"}},\"textColor\":\"slate-600\"} -->\n      <p style=\"font-size:1rem;line-height:1.5;color:#475569\">Equipadas con espacios cómodos que fomentan la confianza y la práctica oral desde el primer día.</p>\n      <!-- /wp:paragraph -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"width\":\"33.33%\"} -->\n    <div class=\"wp-block-column\" style=\"flex-basis:33.33%\">\n      <!-- wp:image {\"id\":15,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"12px\"}}} -->\n      <figure class=\"wp-block-image size-large has-custom-border\"><img src=\"http://localhost:8080/wp-content/uploads/2026/06/IMG_8810.jpg\" alt=\"Clase grupal amplia\" class=\"wp-image-15\" style=\"border-radius:12px;width:100%;height:240px;object-fit:cover\" /></figure>\n      <!-- /wp:image -->\n      <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\",\"fontWeight\":\"600\"}},\"textColor\":\"slate-900\"} -->\n      <h3 class=\"wp-block-heading\" style=\"font-size:1.5rem;font-weight:600;color:#0f172a;margin-top:20px;margin-bottom:8px\">Aprendizaje Dinámico</h3>\n      <!-- /wp:heading -->\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1rem\",\"lineHeight\":\"1.5\"}},\"textColor\":\"slate-600\"} -->\n      <p style=\"font-size:1rem;line-height:1.5;color:#475569\">Experimenta un entrenamiento práctico de inglés que se aplica directamente en tu vida diaria y laboral.</p>\n      <!-- /wp:paragraph -->\n    </div>\n    <!-- /wp:column -->\n  </div>\n  <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->','Inicio','','inherit','closed','closed','','8-revision-v1','','','2026-06-11 19:45:06','2026-06-11 19:45:06','',8,'http://localhost:8080/?p=19',0,'revision','',0),(20,0,'2026-06-11 20:09:20','2026-06-11 20:09:20','<!-- wp:html -->\n\n@import url(\'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800&amp;family=Inter:wght@300;400;500;600;700&amp;display=swap\');\n\n/* Apply global deep dark navy theme */\nbody, .wp-site-blocks, .has-background {\n    background-color: #060b26 !important;\n    color: #f1f5f9 !important;\n    font-family: \'Inter\', sans-serif !important;\n}\n\n/* Global headings styling */\nh1, h2, h3, h4, h5, h6, .wp-block-heading {\n    font-family: \'Outfit\', sans-serif !important;\n    color: #ffffff !important;\n    letter-spacing: -0.5px !important;\n}\n\n/* Header styling override - Dark Glassmorphism */\nheader.wp-block-template-part, .wp-block-template-part header, .site-header {\n    background-color: rgba(6, 11, 38, 0.92) !important;\n    backdrop-filter: blur(12px) !important;\n    -webkit-backdrop-filter: blur(12px) !important;\n    border-bottom: 1px solid rgba(255, 255, 255, 0.08) !important;\n    padding-top: 16px !important;\n    padding-bottom: 16px !important;\n}\n\n/* Site Brand Logo Title */\n.wp-block-site-title a {\n    color: #ffffff !important;\n    font-family: \'Outfit\', sans-serif !important;\n    font-weight: 700 !important;\n    font-size: 20px !important;\n    letter-spacing: -0.5px !important;\n}\n\n/* Header Navigation items */\n.wp-block-navigation a, .wp-block-navigation-item__content {\n    color: #cbd5e1 !important;\n    font-family: \'Inter\', sans-serif !important;\n    font-size: 15px !important;\n    font-weight: 500 !important;\n    transition: all 0.3s ease !important;\n}\n\n.wp-block-navigation a:hover, .wp-block-navigation-item__content:hover {\n    color: #f26419 !important; /* Safety Orange hover */\n    text-shadow: 0 0 10px rgba(242, 100, 25, 0.3) !important;\n}\n\n/* Footer styling override */\nfooter.wp-block-template-part, .wp-block-template-part footer, .site-footer {\n    background-color: #030616 !important;\n    border-top: 1px solid rgba(255, 255, 255, 0.08) !important;\n    padding-top: 60px !important;\n    padding-bottom: 40px !important;\n}\n\nfooter p, footer span, footer a {\n    color: #94a3b8 !important;\n    font-family: \'Inter\', sans-serif !important;\n}\n\nfooter a:hover {\n    color: #f26419 !important;\n}\n\n/* Hero section gradient glow styling */\n.fluent-hero {\n    background: radial-gradient(circle at 85% 25%, rgba(242, 100, 25, 0.07), transparent 45%), \n                radial-gradient(circle at 15% 75%, rgba(0, 180, 216, 0.04), transparent 45%),\n                #060b26 !important;\n    position: relative;\n    overflow: hidden;\n    border-bottom: 1px solid rgba(255, 255, 255, 0.04);\n}\n\n/* Glowing container for hero image */\n.fluent-img-glow {\n    border-radius: 20px !important;\n    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.6), 0 0 40px rgba(242, 100, 25, 0.12) !important;\n    transition: all 0.5s cubic-bezier(0.165, 0.84, 0.44, 1) !important;\n    border: 1px solid rgba(255, 255, 255, 0.06) !important;\n}\n\n.fluent-img-glow:hover {\n    transform: translateY(-4px) scale(1.01) !important;\n    box-shadow: 0 30px 60px -12px rgba(0, 0, 0, 0.7), 0 0 50px rgba(242, 100, 25, 0.22) !important;\n}\n\n/* Meet the Founder section styles */\n.fluent-founder-section {\n    background-color: #0a0f2b !important;\n    border-bottom: 1px solid rgba(255, 255, 255, 0.04);\n}\n\n.fluent-img-normal {\n    border-radius: 20px !important;\n    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4) !important;\n    transition: all 0.4s ease !important;\n    border: 1px solid rgba(255, 255, 255, 0.06) !important;\n}\n\n.fluent-img-normal:hover {\n    transform: scale(1.01) !important;\n    box-shadow: 0 25px 45px rgba(0, 0, 0, 0.5) !important;\n}\n\n/* Gallery Section styling */\n.fluent-gallery-section {\n    background-color: #060b26 !important;\n}\n\n/* Premium Glassmorphic Cards */\n.fluent-card {\n    background-color: #0d1235 !important;\n    border: 1px solid rgba(255, 255, 255, 0.06) !important;\n    border-radius: 20px !important;\n    padding: 28px !important;\n    transition: all 0.4s cubic-bezier(0.165, 0.84, 0.44, 1) !important;\n    box-shadow: 0 10px 30px -10px rgba(0, 0, 0, 0.5) !important;\n}\n\n.fluent-card:hover {\n    transform: translateY(-8px) !important;\n    border-color: rgba(242, 100, 25, 0.35) !important;\n    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.6), 0 0 30px rgba(242, 100, 25, 0.08) !important;\n}\n\n.fluent-card img {\n    border-radius: 12px !important;\n    transition: transform 0.5s ease !important;\n}\n\n.fluent-card:hover img {\n    transform: scale(1.03) !important;\n}\n\n/* WhatsApp CTA Button */\n.fluent-btn-whatsapp a {\n    background-color: #25d366 !important;\n    border: none !important;\n    color: #ffffff !important;\n    box-shadow: 0 4px 14px rgba(37, 211, 102, 0.25) !important;\n    transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) !important;\n    border-radius: 8px !important;\n    padding: 12px 24px !important;\n}\n\n.fluent-btn-whatsapp a:hover {\n    transform: translateY(-2px) !important;\n    box-shadow: 0 6px 20px rgba(37, 211, 102, 0.4), 0 0 15px rgba(37, 211, 102, 0.2) !important;\n}\n\n/* TikTok CTA Button */\n.fluent-btn-tiktok a {\n    background-color: transparent !important;\n    border: 2px solid rgba(255, 255, 255, 0.3) !important;\n    color: #ffffff !important;\n    transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) !important;\n    border-radius: 8px !important;\n    padding: 10px 22px !important;\n}\n\n.fluent-btn-tiktok a:hover {\n    background-color: #ffffff !important;\n    border-color: #ffffff !important;\n    color: #060b26 !important;\n    transform: translateY(-2px) !important;\n    box-shadow: 0 6px 20px rgba(255, 255, 255, 0.15) !important;\n}\n\n<!-- /wp:html -->\n<!-- wp:group {\"metadata\":{\"name\":\"Hero Section\"},\"align\":\"full\",\"className\":\"fluent-hero\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"90px\",\"bottom\":\"90px\",\"left\":\"24px\",\"right\":\"24px\"},\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\"}},\"color\":{\"background\":\"#060b26\"}},\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull fluent-hero has-white-color has-background-color has-text-color\" style=\"margin-top:0px;margin-bottom:0px;padding-top:90px;padding-bottom:90px;padding-left:24px;padding-right:24px;background-color:#060b26\">\n  <!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"48px\",\"left\":\"48px\"}}}} -->\n  <div class=\"wp-block-columns alignwide\">\n    <!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\"} -->\n    <div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\">\n      <!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"3.5rem\",\"fontWeight\":\"800\",\"lineHeight\":\"1.25\"}},\"textColor\":\"white\"} -->\n      <h1 class=\"wp-block-heading has-white-color has-text-color\" style=\"font-size:3.5rem;font-weight:800;line-height:1.25\">Welcome to<br />Fluent Futures</h1>\n      <!-- /wp:heading -->\n\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"lineHeight\":\"1.65\"}},\"textColor\":\"slate-300\"} -->\n      <p style=\"font-size:1.25rem;line-height:1.65;color:#cbd5e1;margin:24px 0 36px 0\">At Fluent Futures, we help students communicate with confidence in everyday English. Our goal is to make English practical, useful, and easy to apply in real life, work, and daily conversations.</p>\n      <!-- /wp:paragraph -->\n\n      <!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\",\"orientation\":\"horizontal\"}} -->\n      <div class=\"wp-block-buttons\">\n        <!-- wp:button {\"className\":\"is-style-fill fluent-btn-whatsapp\",\"textColor\":\"white\"} -->\n        <div class=\"wp-block-button is-style-fill fluent-btn-whatsapp\"><a class=\"wp-block-button__link has-white-color has-text-color wp-element-button\" href=\"https://wa.me/14077605707\" style=\"font-weight:700\" target=\"_blank\" rel=\"noreferrer noopener\">Contact via WhatsApp</a></div>\n        <!-- /wp:button -->\n\n        <!-- wp:button {\"className\":\"is-style-outline fluent-btn-tiktok\",\"textColor\":\"white\"} -->\n        <div class=\"wp-block-button is-style-outline fluent-btn-tiktok\"><a class=\"wp-block-button__link has-white-color has-text-color wp-element-button\" href=\"https://www.tiktok.com/@fluentfutures.8\" style=\"font-weight:700\" target=\"_blank\" rel=\"noreferrer noopener\">Follow on TikTok</a></div>\n        <!-- /wp:button -->\n      </div>\n      <!-- /wp:buttons -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\"} -->\n    <div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\">\n      <!-- wp:image {\"id\":12,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"fluent-img-glow\"} -->\n      <figure class=\"wp-block-image size-large fluent-img-glow\"><img src=\"http://localhost:8080/wp-content/uploads/2026/06/IMG_8347.jpeg\" alt=\"Students studying together\" class=\"wp-image-12\" style=\"width:100%;height:auto\" /></figure>\n      <!-- /wp:image -->\n    </div>\n    <!-- /wp:column -->\n  </div>\n  <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Meet the Founder Section\"},\"align\":\"full\",\"className\":\"fluent-founder-section\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"90px\",\"bottom\":\"90px\",\"left\":\"24px\",\"right\":\"24px\"}},\"color\":{\"background\":\"#0a0f2b\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull fluent-founder-section has-background-color\" style=\"padding-top:90px;padding-bottom:90px;padding-left:24px;padding-right:24px;background-color:#0a0f2b\">\n  <!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"48px\",\"left\":\"48px\"}}}} -->\n  <div class=\"wp-block-columns alignwide\">\n    <!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"45%\"} -->\n    <div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:45%\">\n      <!-- wp:image {\"id\":11,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"fluent-img-normal\"} -->\n      <figure class=\"wp-block-image size-large fluent-img-normal\"><img src=\"http://localhost:8080/wp-content/uploads/2026/06/168f3f2f-11c2-415d-b51c-d713d1626e79.jpg\" alt=\"Teacher Angie teaching classroom\" class=\"wp-image-11\" style=\"width:100%;height:auto\" /></figure>\n      <!-- /wp:image -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"55%\"} -->\n    <div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:55%\">\n      <!-- wp:heading {\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"2.5rem\",\"fontWeight\":\"700\"}},\"textColor\":\"white\"} -->\n      <h2 class=\"wp-block-heading\" style=\"font-size:2.5rem;font-weight:700;color:#ffffff\">Teacher Angie — Founder of Fluent Futures</h2>\n      <!-- /wp:heading -->\n\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.125rem\",\"lineHeight\":\"1.75\"}},\"textColor\":\"slate-300\"} -->\n      <p style=\"font-size:1.125rem;line-height:1.75;color:#cbd5e1;margin-top:24px\">I am passionate about teaching English and helping my students grow. Fluent Futures is more than a school — it is a community where students feel supported, motivated, and confident to improve every day. We also have a bit of fun.</p>\n      <!-- /wp:paragraph -->\n\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.125rem\",\"lineHeight\":\"1.75\"}},\"textColor\":\"slate-300\"} -->\n      <p style=\"font-size:1.125rem;line-height:1.75;color:#cbd5e1;margin-top:16px\">I give the latino community a voice and bridge the gap between cultures in Austin.</p>\n      <!-- /wp:paragraph -->\n    </div>\n    <!-- /wp:column -->\n  </div>\n  <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"School Gallery Section\"},\"align\":\"full\",\"className\":\"fluent-gallery-section\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"90px\",\"bottom\":\"90px\",\"left\":\"24px\",\"right\":\"24px\"}},\"color\":{\"background\":\"#060b26\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull fluent-gallery-section has-background-color\" style=\"padding-top:90px;padding-bottom:90px;padding-left:24px;padding-right:24px;background-color:#060b26\">\n  <!-- wp:heading {\"textAlign\":\"center\",\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"2.5rem\",\"fontWeight\":\"700\"}},\"textColor\":\"white\"} -->\n  <h2 class=\"wp-block-heading has-text-align-center\" style=\"font-size:2.5rem;font-weight:700;color:#ffffff;margin-bottom:56px\">Our Community &amp; Learning Space</h2>\n  <!-- /wp:heading -->\n\n  <!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"32px\",\"left\":\"32px\"}}}} -->\n  <div class=\"wp-block-columns alignwide\">\n    <!-- wp:column {\"width\":\"33.33%\",\"className\":\"fluent-card\"} -->\n    <div class=\"wp-block-column fluent-card\" style=\"flex-basis:33.33%\">\n      <!-- wp:image {\"id\":13,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n      <figure class=\"wp-block-image size-large\"><img src=\"http://localhost:8080/wp-content/uploads/2026/06/IMG_7220.jpg\" alt=\"School campus exterior\" class=\"wp-image-13\" style=\"width:100%;height:240px;object-fit:cover\" /></figure>\n      <!-- /wp:image -->\n      <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\",\"fontWeight\":\"600\"}},\"textColor\":\"white\"} -->\n      <h3 class=\"wp-block-heading\" style=\"font-size:1.5rem;font-weight:600;color:#ffffff;margin-top:24px;margin-bottom:12px\">Our Campus</h3>\n      <!-- /wp:heading -->\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1rem\",\"lineHeight\":\"1.6\"}},\"textColor\":\"slate-300\"} -->\n      <p style=\"font-size:1rem;line-height:1.6;color:#cbd5e1\">A welcoming and modern campus designed to foster collaboration and interactive learning.</p>\n      <!-- /wp:paragraph -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"width\":\"33.33%\",\"className\":\"fluent-card\"} -->\n    <div class=\"wp-block-column fluent-card